// ============================================================
// FSRS-5 ENGINE (Free Spaced Repetition Scheduler v5)
// Baseado em: https://github.com/open-spaced-repetition/awesome-fsrs/wiki/The-Algorithm
// Benchmark: >700M reviews; ~20-30% menos revisões que SM-2 à mesma retenção
// ============================================================
const FSRS_W = [0.40255, 1.18385, 3.173, 15.69105, 7.1949, 0.5345, 1.4604, 0.0046, 1.54575, 0.1192, 1.01925, 1.9395, 0.11, 0.29605, 2.2698, 0.2315, 2.9898, 0.51655, 0.6621];
const FSRS_DECAY = -0.5;           // FSRS-4.5/5 forgetting curve
const FSRS_FACTOR = Math.pow(0.9, 1 / FSRS_DECAY) - 1;  // 19/81
const FSRS_MAX_INTERVAL = 36500;
// leech threshold dinâmico (ver getLeechThreshold no painel ⚙️)

// Retenção alvo (persistida; default 90%)
function getTargetRetention() {
  try {
    const v = parseFloat(localStorage.getItem('medreview_fsrs_retention'));
    if (!isNaN(v) && v >= 0.8 && v <= 0.97) return v;
  } catch (e) {}
  return 0.9;
}
function setTargetRetention(v) {
  v = Math.min(0.97, Math.max(0.8, v));
  try { localStorage.setItem('medreview_fsrs_retention', String(v)); } catch (e) {}
  renderRoute();
}

// Curva de esquecimento FSRS-5: R(t,S) = (1 + FACTOR·t/S)^DECAY
function fsrsRetrievability(elapsedDays, stability) {
  if (!stability || stability <= 0) return 0;
  const t = Math.max(0, elapsedDays);
  return Math.pow(1 + FSRS_FACTOR * t / stability, FSRS_DECAY);
}

// Intervalo (em dias) para atingir a retenção alvo r
function fsrsIntervalFor(stability, r) {
  const ivl = stability / FSRS_FACTOR * (Math.pow(r, 1 / FSRS_DECAY) - 1);
  return Math.max(0.1, Math.min(FSRS_MAX_INTERVAL, ivl));
}

// Dificuldade inicial D0(G) = w4 - e^(w5·(G-1)) + 1
function fsrsInitialDifficulty(g) {
  return Math.min(10, Math.max(1, FSRS_W[4] - Math.exp(FSRS_W[5] * (g - 1)) + 1));
}

// Nova dificuldade com linear damping + mean reversion para D0(4)
function fsrsNextDifficulty(d, g) {
  const linDamp = (10 - d) / 9;
  const dPrime = d - FSRS_W[6] * (g - 3) * linDamp;
  const d0g4 = fsrsInitialDifficulty(4);
  const dNext = FSRS_W[7] * d0g4 + (1 - FSRS_W[7]) * dPrime;
  return Math.min(10, Math.max(1, dNext));
}

// Estabilidade inicial S0(G) = w[G-1]
function fsrsInitialStability(g) {
  return Math.max(0.1, FSRS_W[g - 1]);
}

// Estabilidade pós-recall: S·(e^w8·(11-D)·S^-w9·(e^(w10·(1-R))-1)·[hard·w15|easy·w16]+1)
function fsrsStabilityAfterRecall(d, s, r, g) {
  let inc = Math.exp(FSRS_W[8]) * (11 - d) * Math.pow(s, -FSRS_W[9]) * (Math.exp(FSRS_W[10] * (1 - r)) - 1);
  if (g === 2) inc *= FSRS_W[15];
  if (g === 4) inc *= FSRS_W[16];
  return Math.max(0.1, s * (1 + inc));
}

// Estabilidade pós-lapse: w11·D^-w12·((S+1)^w13 - 1)·e^(w14·(1-R))
function fsrsStabilityAfterForget(d, s, r) {
  return Math.max(0.1, FSRS_W[11] * Math.pow(d, -FSRS_W[12]) * (Math.pow(s + 1, FSRS_W[13]) - 1) * Math.exp(FSRS_W[14] * (1 - r)));
}

// Mesmo dia: S' = S·e^(w17·(G-3+w18))
function fsrsSameDayStability(s, g) {
  return Math.max(0.1, s * Math.exp(FSRS_W[17] * (g - 3 + FSRS_W[18])));
}

// Estado legível da carta (state = new|learning|review|relearning)
function fsrsCardState(card) {
  if (isCardNew(card)) return 'new';
  return card.fsrsState || 'review';
}

// Migração SM-2 → FSRS: S a partir do intervalo, D a partir do EF
function fsrsMigrateCard(card) {
  if (card.fsrsS !== undefined && card.fsrsD !== undefined) return;
  const ivl = card.interval || 0;
  if (ivl <= 0) {
    card.fsrsS = null; card.fsrsD = null;
  } else {
    card.fsrsS = Math.max(0.1, ivl);
    const ef = card.easeFactor || 2.5;
    // EF 2.5→D 5; EF 3.0→D ~2; EF 1.3→D ~9 (aproximação linear)
    card.fsrsD = Math.min(10, Math.max(1, 5 + (2.5 - ef) * 4));
  }
  if (card.lapses === undefined) card.lapses = 0;
}

// Preview dos intervalos FSRS-5 para os 4 botões de qualidade
function getQualityIntervals(card) {
  const r = getTargetRetention();
  const now = Date.now();
  const lastReview = card.lastReviewMs || null;
  const elapsedDays = lastReview ? Math.max(0, (now - lastReview) / 86400000) : 0;
  const migrated = card.fsrsS !== undefined && card.fsrsS !== null;

  // Carta nova: S/D ainda não existem — usa estabilidade inicial S0(G)
  if (isCardNew(card) || !migrated) {
    const mk = (g) => {
      const s0 = fsrsInitialStability(g);
      const ivl = fsrsIntervalFor(s0, r);
      return { label: formatInterval(ivl), value: ivl };
    };
    const a = mk(1), h = mk(2), g3 = mk(3), e = mk(4);
    return {
      again: { label: a.label, value: a.value, rep: 0, newEf: 2.5, g: 1, state: 'learning' },
      hard:  { label: h.label, value: h.value, rep: 1, newEf: 2.5, g: 2, state: 'learning' },
      good:  { label: g3.label, value: g3.value, rep: 1, newEf: 2.5, g: 3, state: 'review' },
      easy:  { label: e.label, value: e.value, rep: 1, newEf: 2.5, g: 4, state: 'review' }
    };
  }

  const S = card.fsrsS;
  const D = card.fsrsD || 5;
  const R = fsrsRetrievability(elapsedDays, S);

  const mk = (g) => {
    let newS, newState;
    if (elapsedDays < 1) {
      // Revisão no mesmo dia: S' = S·e^(w17·(G-3+w18))
      newS = fsrsSameDayStability(S, g);
      newState = g === 1 ? 'relearning' : (card.fsrsState === 'learning' ? 'review' : card.fsrsState || 'review');
    } else if (g === 1) {
      newS = fsrsStabilityAfterForget(D, S, R);
      newState = 'relearning';
    } else {
      newS = fsrsStabilityAfterRecall(D, S, R, g);
      newState = 'review';
    }
    const ivl = fsrsIntervalFor(newS, r);
    const newD = fsrsNextDifficulty(D, g);
    return { label: formatInterval(ivl), value: ivl, newS, newD, g, state: newState };
  };

  const out = { again: mk(1), hard: mk(2), good: mk(3), easy: mk(4) };
  // rep/newEf mantidos para compatibilidade com estatísticas legadas
  out.again.rep = 0; out.again.newEf = card.easeFactor || 2.5;
  out.hard.rep = Math.max(1, card.repetitions || 0);
  out.hard.newEf = card.easeFactor || 2.5;
  out.good.rep = (card.repetitions || 0) + 1;
  out.good.newEf = card.easeFactor || 2.5;
  out.easy.rep = (card.repetitions || 0) + 1;
  out.easy.newEf = card.easeFactor || 2.5;
  return out;
}

