function logCardEvaluation(cardId, quality, containerId) {
  const history = getStoredEvalHistory();
  const dateStr = new Date().toISOString().split('T')[0];
  history.push({
    cardId,
    quality, // 'again', 'hard', 'good', 'easy'
    containerId: containerId || 'tutoria',
    date: dateStr,
    timestamp: Date.now()
  });
  // Cap at last 2000 events to stay performant in localStorage
  if (history.length > 2000) {
    history.splice(0, history.length - 2000);
  }
  try {
    localStorage.setItem(EVAL_HISTORY_KEY, JSON.stringify(history));
  } catch (e) {}
}

function logCardEvaluation(cardId, quality, containerId, fsrsMeta) {
  const history = getStoredEvalHistory();
  const dateStr = new Date().toISOString().split('T')[0];
  const entry = {
    cardId,
    quality, // 'again', 'hard', 'good', 'easy' (1-4 no FSRS)
    containerId: containerId || 'tutoria',
    date: dateStr,
    timestamp: Date.now()
  };
  // Metadados FSRS (para futura otimização de pesos — formato fsrs-style)
  if (fsrsMeta) {
    entry.rating = fsrsMeta.g;            // 1-4
    entry.state = fsrsMeta.state;         // new/learning/review/relearning
    entry.deltaT = fsrsMeta.deltaT;       // dias desde a última revisão
    entry.S_before = fsrsMeta.S_before;
    entry.D_before = fsrsMeta.D_before;
    entry.R_before = fsrsMeta.R_before;
    entry.S_after = fsrsMeta.S_after;
    entry.D_after = fsrsMeta.D_after;
  }
  history.push(entry);
  // Cap at last 2000 events to stay performant in localStorage
  if (history.length > 2000) {
    history.splice(0, history.length - 2000);
  }
  try {
    localStorage.setItem(EVAL_HISTORY_KEY, JSON.stringify(history));
  } catch (e) {}
}
